import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, seq, active)
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def add_to_book(side, oid, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def pop_best_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return oid, o
        return None, None

    def pop_best_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return oid, o
        return None, None

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                sid, sorder = pop_best_sell()
                if sid is None:
                    break
                if typ != 'market' and sorder['price'] > price:
                    break
                trade_qty = min(remaining, sorder['qty'])
                trades.append([oid, sid, sorder['price'], trade_qty])
                remaining -= trade_qty
                sorder['qty'] -= trade_qty
                if sorder['qty'] == 0:
                    sorder['active'] = False
            if typ == 'limit' and remaining > 0:
                add_to_book('buy', oid, price, remaining, seq)
        else:  # sell
            while remaining > 0:
                bid, border = pop_best_buy()
                if bid is None:
                    break
                if typ != 'market' and border['price'] < price:
                    break
                trade_qty = min(remaining, border['qty'])
                trades.append([bid, oid, border['price'], trade_qty])
                remaining -= trade_qty
                border['qty'] -= trade_qty
                if border['qty'] == 0:
                    border['active'] = False
            if typ == 'limit' and remaining > 0:
                add_to_book('sell', oid, price, remaining, seq)

    return trades

